"""Bounded business ledger for the case's owned HTTP dependency."""
import hashlib,json
CAPACITY=3
MAX_STALE_NS=600_000_000_000
MAX_AGE_NS=7_200_000_000_000
INTERVAL_NS=200_000_000

def canonical(payload):
    return json.dumps(payload,ensure_ascii=False,sort_keys=True,separators=(',',':'))

def read_cached(db,now):
    row=db.execute('SELECT value,as_of_ns FROM cache WHERE id=1').fetchone()
    if not row or now-row[1]>MAX_STALE_NS or row[1]>now:
        return 503,dict(state='unavailable',reason='cache_stale_or_missing')
    return 200,dict(state='cached',value=json.loads(row[0]),as_of_ns=row[1],max_stale_ns=MAX_STALE_NS)

def accept(db,key,payload,now):
    encoded=canonical(payload)
    db.execute('BEGIN IMMEDIATE')
    try:
        existing=db.execute('SELECT payload,state FROM ledger WHERE business_key=?',(key,)).fetchone()
        if existing:
            db.commit()
            if existing[0]!=encoded:return 409,dict(state='conflict',business_key=key)
            return 200 if existing[1]=='confirmed'else 202,dict(state=existing[1],business_key=key)
        count=db.execute("SELECT count(*) FROM ledger WHERE state!='confirmed'").fetchone()[0]
        expired=db.execute("SELECT count(*) FROM ledger WHERE state!='confirmed'AND created_ns<?",(now-MAX_AGE_NS,)).fetchone()[0]
        if count>=CAPACITY or expired:
            db.rollback()
            return 503,dict(state='rejected',reason='capacity'if count>=CAPACITY else'backlog_expired',business_key=key)
        db.execute("INSERT INTO ledger(business_key,payload,created_ns,state) VALUES(?,?,?,'accepted')",(key,encoded,now))
        db.commit()
        return 202,dict(state='accepted',business_key=key)
    except BaseException:
        db.rollback()
        raise

def status(db,key):
    row=db.execute('SELECT state,receipt FROM ledger WHERE business_key=?',(key,)).fetchone()
    if not row:return 404,dict(state='missing',business_key=key)
    return 200,dict(state=row[0],business_key=key,receipt=json.loads(row[1])if row[1]else None)

def reconcile(db,upstream,now):
    earliest=db.execute('SELECT not_before_ns FROM pacing WHERE id=1').fetchone()[0]
    if now<earliest:return dict(attempted=False,reason='rate_limit',not_before_ns=earliest)
    row=db.execute("SELECT business_key,payload,created_ns,state FROM ledger WHERE state IN('accepted','unknown')ORDER BY created_ns,business_key LIMIT 1").fetchone()
    if not row:return dict(attempted=False,reason='no_automatic_work')
    key,encoded,created,state=row
    if now-created>MAX_AGE_NS:
        db.execute("UPDATE ledger SET state='manual'WHERE business_key=?",(key,));db.commit()
        return dict(attempted=False,reason='expired_manual',business_key=key)
    db.execute('UPDATE pacing SET not_before_ns=?WHERE id=1',(now+INTERVAL_NS,));db.commit()
