        # Unknown submissions are looked up before a further idempotent send.
        response=upstream.lookup(key)if state=='unknown'else upstream.submit(key,json.loads(encoded))
        code,body=response
        if code==404 and state=='unknown':
            # The owned counterpart advertises a strongly consistent receipt lookup.
            # A production provider without this contract must use manual resolution.
            db.execute("UPDATE ledger SET state='accepted'WHERE business_key=?",(key,))
        elif code==429:
            retry=body['retry_after_ns']
            if type(retry)is not int or retry<INTERVAL_NS:raise ValueError('bounded retry contract required')
            db.execute('UPDATE pacing SET not_before_ns=?WHERE id=1',(now+retry,))
        elif code==200:
            if body.get('business_key')!=key or body.get('payload_sha256')!=hashlib.sha256(encoded.encode()).hexdigest()or not isinstance(body.get('receipt_id'),str)or not body['receipt_id']:
                raise ValueError('receipt does not confirm this business operation')
            db.execute("UPDATE ledger SET state='confirmed',receipt=?WHERE business_key=?",(canonical(body),key))
        else:
            db.execute("UPDATE ledger SET state='manual'WHERE business_key=?",(key,))
        db.commit()
    except (OSError,TimeoutError,ValueError,ConnectionError):
        db.execute("UPDATE ledger SET state='unknown'WHERE business_key=?",(key,));db.commit()
    return dict(attempted=True,business_key=key,state=db.execute('SELECT state FROM ledger WHERE business_key=?',(key,)).fetchone()[0])

def can_leave_emergency(db):
    # Unknown/expired work stays visible; leaving never deletes or forgets it.
    return db.execute("SELECT count(*) FROM ledger WHERE state!='confirmed'").fetchone()[0]==0

